(r/'captions').mkdir(exist_ok=True)
for x,c in zip(items,links['canva']):
 x['canva']=c['urls']['edit_url'];x['figma']=links['figma'];x['duracion_s']=22;x['placas']=[f'carruseles/{x["id"]}/{x["id"]}-{i:02}.png' for i in range(1,6)]
 (r/'captions'/(x['id']+'.txt')).write_text(x['caption']+'\n\n#ÍndigoPy #CiudadDelEste\n')
(r/'INDICE.json').write_text(json.dumps(dict(fecha='2026-10-26',coleccion=items),ensure_ascii=False,indent=2))
md='# Índigo · Estudios de prendas\n\nEntrega del 26 de octubre de 2026. Dos Reels de 22 segundos y dos carruseles de cinco placas. Sin grabación nueva ni locución. Referencias históricas, sin promesas de stock.\n\n'
for x in items:
 md+=f'## {x["titulo"]}\n\nReel: `reels/{x["reel"]}.mp4` · Carrusel: `carruseles/{x["id"]}/`\n\n[Canva editable]({x["canva"]}) · [Figma editable]({x["figma"]})\n\nCaption: {x["caption"]}\n\nFuentes:\n\n'+''.join('- '+u+'\n' for u in x['fuentes'])+'\n'
md+='## Referencias de dirección de arte\n\n- ARKET: https://www.arket.com/en-gb/women/edits/ss26-lookbook/\n- Trabajo editorial COS: https://www.leonsanli.com/work/ss26-campaign\n\nSe consultaron como referencias de jerarquía, ritmo y espacio. No se incorporaron fotografías, prendas o logos de esas marcas. El perfil de Índigo no respondió al acceso web de esta sesión; las imágenes locales mantienen las fuentes registradas y verificadas en las entregas anteriores.\n'
(r/'INDICE.md').write_text(md)
css='''@font-face{font-family:Inter;src:url(editor/public/fonts/inter-500.woff2)}@font-face{font-family:Cormorant;src:url(editor/public/fonts/cormorant-normal.ttf)}*{box-sizing:border-box}body{margin:0;background:#F4F0E6;color:#20251B;font:15px/1.6 Inter,Arial,sans-serif}header{background:#30371F;color:#F4F0E6;padding:55px max(28px,calc((100vw - 1180px)/2));display:flex;gap:50px;align-items:center;justify-content:space-between}header img{width:135px;height:135px;border-radius:50%}.eyebrow{font-size:11px;letter-spacing:3px}h1{font:600 clamp(54px,7vw,92px)/.95 Cormorant;margin:24px 0}header p{max-width:630px;color:#CBD0B2;font-size:13px}main,footer{max-width:1236px;padding:30px 28px;margin:auto}section{padding:30px 0 50px;border-bottom:1px solid #CBD0B2}.heading{display:flex;align-items:center;justify-content:space-between;gap:25px}h2{font:600 48px/1.1 Cormorant;margin:0 0 20px}a{color:inherit;text-underline-offset:4px}.links{display:flex;flex-wrap:wrap;gap:17px;font-size:12px;color:#4F5533}video{width:min(360px,100%);aspect-ratio:9/16;display:block;background:#30371F}.reel{display:grid;grid-template-columns:360px 1fr;gap:45px;align-items:center;margin:24px 0}.reel p{max-width:440px}.strip{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:18px}.strip a{flex:0 0 220px;scroll-snap-align:start}.strip img{width:220px;height:275px;display:block}.strip span{display:block;font-size:11px;padding-top:6px;color:#4F5533}summary{cursor:pointer}.caption{max-width:780px;font-size:13px}button{font:12px Inter;color:#F4F0E6;background:#4F5533;border:0;padding:10px 15px;cursor:pointer}footer{font-size:12px;display:flex;gap:20px;flex-wrap:wrap;padding-bottom:45px}@media(max-width:700px){header img{display:none}.heading{display:block}h2{font-size:40px}.reel{grid-template-columns:1fr;gap:16px}video{margin:auto}.strip a{flex-basis:76vw}.strip img{width:76vw;height:auto}}'''
sections=[]
for n,x in enumerate(items):
 strip=''.join(f'<a href="{p}" target="_blank"><img src="{p}" alt="{html.escape(x["titulo"])} · placa {i+1}"><span>{i+1:02} / 05 · Abrir placa</span></a>' for i,p in enumerate(x['placas']))
 sections.append(f'''<section><div class="heading"><div><div class="eyebrow">ESTUDIO {n+1:02}</div><h2>{x['titulo']}</h2></div><nav class="links"><a target="_blank" href="{x['canva']}">Editar en Canva ↗</a><a target="_blank" href="{x['figma']}">Editar en Figma ↗</a></nav></div><div class="reel"><video controls playsinline preload="metadata" poster="portadas/{x['reel']}.png" aria-label="{html.escape(x['titulo'])}"><source src="reels/{x['reel']}.mp4" type="video/mp4"></video><div><div class="eyebrow">REEL · 22 SEGUNDOS</div><p>{html.escape(x['caption'])}</p><nav class="links"><a download href="reels/{x['reel']}.mp4">Descargar MP4</a><a download href="portadas/{x['reel']}.png">Portada</a></nav></div></div><div class="eyebrow" style="margin-bottom:18px">CARRUSEL · 5 PLACAS · 1080 × 1350</div><div class="strip">{strip}</div><details><summary>Caption y archivos editables</summary><p class="caption" id="caption-{x['id']}">{html.escape(x['caption'])}</p><button data-copy="caption-{x['id']}">Copiar caption</button><p class="links"><a download href="captions/{x['id']}.txt">Caption .txt</a><a download href="editables/{x['id']}-canva.pdf">PDF</a><a download href="editables/{x['id']}-canva.html">HTML editable</a></p></details></section>''')
script="document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()})));document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{await navigator.clipboard.writeText(document.getElementById(b.dataset.copy).innerText);b.textContent='Caption copiado'}));"
(r/'index.html').write_text('<!doctype html><html lang="es-PY"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Índigo · Estudios de prendas</title><style>'+css+'</style></head><body><header><div><div class="eyebrow">ÍNDIGO PY · OCTUBRE 2026</div><h1>Estudios<br>de prendas.</h1><p>Dos Reels y dos carruseles. Fotografías reales, identidad olivo y composiciones editoriales. Editables en Canva y Figma.</p></div><img src="editor/public/brand/logo.jpg" alt="Logo oficial Índigo"></header><main>'+''.join(sections)+'</main><footer><a href="PROMPT-DIRECCION-CREATIVA.md">Prompt de dirección creativa</a><a href="INDICE.md">Conceptos y fuentes</a><a href="LEEME.md">Editables</a><a href="INDIGO-ESTUDIOS-DE-PRENDAS.zip" download>Descargar colección completa ↗</a><span>Revisión humana y publicación manual.</span></footer><script>'+script+'</script></body></html>')
